    def countSteppingNumbers(self, low: int, high: int) -> list[int]:
        res = []
        if low == 0:
            res.append(0)

        q = deque(range(1, 10))
        while q:
            curr = q.popleft()
            if curr > high:
                continue
            if curr >= low:
                res.append(curr)
            last = curr % 10
            if last > 0:
                nxt = curr * 10 + (last - 1)
                if nxt <= high:
                    q.append(nxt)
            if last < 9:
                nxt = curr * 10 + (last + 1)
                if nxt <= high:
                    q.append(nxt)

        return sorted(res)
