class Solution {
public:
    std::vector<int> countSteppingNumbers(int low, int high) {
        std::vector<int> res;
        if (low == 0) res.push_back(0);

        std::queue<long long> q;
        for (int i = 1; i <= 9; ++i) q.push(i);

        while (!q.empty()) {
            long long curr = q.front();
            q.pop();
            if (curr > high) continue;
            if (curr >= low) res.push_back(curr);

            int last = curr % 10;
            if (last > 0) {
                long long nxt = curr * 10 + (last - 1);
                if (nxt <= high) q.push(nxt);
            }
            if (last < 9) {
                long long nxt = curr * 10 + (last + 1);
                if (nxt <= high) q.push(nxt);
            }
        }
        std::sort(res.begin(), res.end());
        return res;
    }
};

class Solution {
    public java.util.List<Integer> countSteppingNumbers(int low, int high) {
        java.util.List<Integer> res = new java.util.ArrayList<>();
        if (low == 0) res.add(0);

        java.util.Queue<Long> q = new java.util.LinkedList<>();
        for (long i = 1; i <= 9; i++) q.add(i);

        while (!q.isEmpty()) {
            long curr = q.poll();
            if (curr > high) continue;
            if (curr >= low) res.add((int) curr);

            int last = (int) (curr % 10);
            if (last > 0) {
                long nxt = curr * 10 + (last - 1);
                if (nxt <= high) q.add(nxt);
            }
            if (last < 9) {
                long nxt = curr * 10 + (last + 1);
                if (nxt <= high) q.add(nxt);
            }
        }
        java.util.Collections.sort(res);
        return res;
    }
}

var countSteppingNumbers = function(low, high) {
    const res = [];
    if (low === 0) res.push(0);

    const q = [];
    for (let i = 1; i <= 9; i++) q.push(i);

    while (q.length > 0) {
        const curr = q.shift();
        if (curr > high) continue;
        if (curr >= low) res.push(curr);

        const last = curr % 10;
        if (last > 0) {
            const nxt = curr * 10 + (last - 1);
            if (nxt <= high) q.push(nxt);
        }
        if (last < 9) {
            const nxt = curr * 10 + (last + 1);
            if (nxt <= high) q.push(nxt);
        }
    }
    res.sort((a, b) => a - b);
    return res;
